    fun byId(id: String): Dhikr? = ALL.firstOrNull { it.id == id }
    fun inCategory(cat: Int, favorites: List<String>): List<Dhikr> =
        if (cat == FAVORITES) favorites.mapNotNull { byId(it) } else ALL.filter { it.cat == cat }
}
